// student.cpp - Defining and using a structure
#include <iostream>
#include <string>
using namespace std;

struct Student {
    int roll;
    string name;
    float percent;
};

int main() {
    Student s1;                        // declare a structure variable
    s1.roll = 21;                      // access members with the dot (.)
    s1.name = "Aman Kumar";
    s1.percent = 87.5;

    Student s2 = {22, "Riya Singh", 91.2};   // initialise in one line

    cout << s1.roll << " | " << s1.name << " | " << s1.percent << "%" <<
endl;
    cout << s2.roll << " | " << s2.name << " | " << s2.percent << "%" <<
endl;

    s2.percent = 93.0;                 // members can be changed
    cout << "Updated: " << s2.name << " -> " << s2.percent << "%" << endl;
    return 0;
}

// topper.cpp - Array of structures and a function taking a struct
#include <iostream>
#include <string>
using namespace std;

struct Student {
    int roll;
    string name;
    int marks;
};

void show(const Student &s) {          // pass by const reference
    cout << s.roll << "\t" << s.name << "\t" << s.marks << endl;
}

int main() {
    Student cls[4] = {
        {1, "Aman", 78},
        {2, "Riya", 92},
        {3, "Kabir", 85},
        {4, "Sana", 67}
    };

    cout << "Roll\tName\tMarks" << endl;
    int top = 0;
    for (int i = 0; i < 4; i++) {
        show(cls[i]);
        if (cls[i].marks > cls[top].marks) top = i;
    }
    cout << "Topper: " << cls[top].name << " (" << cls[top].marks << ")" <<
endl;
    return 0;
}

