// pairdemo.cpp - pair and tuple
#include <iostream>
#include <utility>
#include <tuple>
#include <string>
using namespace std;

pair<int, int> minMax(int a[], int n) {
    int mn = a[0], mx = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] < mn) mn = a[i];
        if (a[i] > mx) mx = a[i];
    }
    return make_pair(mn, mx);          // return two values together
}

int main() {
    pair<string, int> city("Patna", 800014);   // name and PIN code
    cout << city.first << " - " << city.second << endl;

    int arr[] = {45, 12, 78, 34, 9};
    pair<int, int> r = minMax(arr, 5);
    cout << "Min = " << r.first << ", Max = " << r.second << endl;

    tuple<string, int, char> stu("Kabir", 16, 'A');   // three values
    cout << get<0>(stu) << ", age " << get<1>(stu)
         << ", grade " << get<2>(stu) << endl;
    return 0;
}

