// phonebook.cpp - map as a dictionary
#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    map<string, string> phone;

    phone["Aman"]  = "98350 11111";       // add with []
    phone["Riya"]  = "70040 22222";
    phone.insert({"Kabir", "62000 33333"}); // add with insert

    cout << "Riya's number: " << phone["Riya"] << endl;
    phone["Riya"] = "70040 99999";        // update
    cout << "Updated: " << phone.at("Riya") << endl;

    cout << "Total contacts: " << phone.size() << endl;

    string who = "Sana";
    if (phone.count(who) == 0)
        cout << who << " is not in the phone book" << endl;

    phone.erase("Aman");                  // delete a key

    cout << "\nAll contacts (sorted by name):" << endl;
    for (auto p : phone)
        cout << p.first << " : " << p.second << endl;
    return 0;
}

// wordfreq.cpp - Count each word using a map
#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    string text = "the cat and the dog and the bird";
    map<string, int> freq;
    string word = "";

    text += " ";
    for (char ch : text) {
        if (ch == ' ') {
            if (word != "") freq[word]++;   // new key starts at 0
            word = "";
        } else {
            word += ch;
        }
    }

    for (auto p : freq)
        cout << p.first << " -> " << p.second << endl;
    return 0;
}

// charcount.cpp - Character frequency using map<char, int>
#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    string s;
    cout << "Enter a word: ";
    cin >> s;

    map<char, int> count;
    for (char ch : s)
        count[ch]++;

    for (auto p : count)
        cout << p.first << " : " << p.second << endl;
    return 0;
}

// marksmap.cpp - Student marks with map<string, vector<int>>
#include <iostream>
#include <map>
#include <vector>
#include <string>
using namespace std;

int main() {
    map<string, vector<int>> result;
    result["Aman"] = {78, 85, 90};
    result["Riya"] = {92, 88, 95};
    result["Sana"] = {65, 70, 72};

    for (auto p : result) {
        int total = 0;
        for (int m : p.second) total += m;
        cout << p.first << " : total " << total
             << ", average " << total / (float)p.second.size() << endl;
    }
    return 0;
}

