#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    map<string, string> dict;
    int choice;
    string word, meaning;

    do {
        cout << "\n1. Add\n2. Search\n3. Delete\n4. Show all\n5. Exit\nChoice: ";
        cin >> choice;
        cin.ignore();
        switch (choice) {
            case 1:
                cout << "Word: "; getline(cin, word);
                cout << "Meaning: "; getline(cin, meaning);
                dict[word] = meaning;
                break;
            case 2:
                cout << "Word: "; getline(cin, word);
                if (dict.count(word)) cout << word << " = " << dict[word] <<
endl;
                else cout << "Not found" << endl;
                break;
            case 3:
                cout << "Word: "; getline(cin, word);
                if (dict.erase(word)) cout << "Deleted" << endl;
                else cout << "Not found" << endl;
                break;
            case 4:
                for (auto p : dict) cout << p.first << " : " << p.second <<
endl;
                break;
            case 5: cout << "Bye" << endl; break;
            default: cout << "Invalid choice" << endl;
        }
    } while (choice != 5);
    return 0;
}
